QuenchTankLidGasketMaker.productStock = {}; QuenchTankLidGasketMaker.buildings = {}; QuenchTankLidGasketMaker.maker = nil; QuenchTankLidGasketMaker.activeMaking = {}; QuenchTankLidGasketMaker.totalProducts = 0; QuenchTankLidGasketMaker.dayTimer = 0
function QuenchTankLidGasketMaker.init() QuenchTankLidGasketMaker.ironStock=12; QuenchTankLidGasketMaker.bronzeStock=10; QuenchTankLidGasketMaker.woodStock=14; QuenchTankLidGasketMaker.leatherStock=12; QuenchTankLidGasketMaker.silverStock=8; QuenchTankLidGasketMaker.goldStock=6; QuenchTankLidGasketMaker.jewelStock=4; QuenchTankLidGasketMaker.pearlStock=4; QuenchTankLidGasketMaker.productStock={}; QuenchTankLidGasketMaker.buildings={}; QuenchTankLidGasketMaker.maker=nil; QuenchTankLidGasketMaker.activeMaking={}; QuenchTankLidGasketMaker.totalProducts=0; QuenchTankLidGasketMaker.dayTimer=0; print("[QuenchTankLidGasketMaker] Royal Quench Tank Lid Gasket Maker System initialized (6 products, 4 buildings)") end
function QuenchTankLidGasketMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; QuenchTankLidGasketMaker.maker={name=n or ("Tesnilkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tesnilkar najet: %s (spretnost: %d)",QuenchTankLidGasketMaker.maker.name,s),"success") end; return true end
function QuenchTankLidGasketMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function QuenchTankLidGasketMaker.build(id) local ok,e=QuenchTankLidGasketMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(QuenchTankLidGasketMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function QuenchTankLidGasketMaker.getQualityBonus() local b=0; for _,bd in ipairs(QuenchTankLidGasketMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function QuenchTankLidGasketMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and QuenchTankLidGasketMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and QuenchTankLidGasketMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and QuenchTankLidGasketMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and QuenchTankLidGasketMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and QuenchTankLidGasketMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and QuenchTankLidGasketMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and QuenchTankLidGasketMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and QuenchTankLidGasketMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #QuenchTankLidGasketMaker.buildings==0 then return false,"Potrebna tesnilna delavnica" end; if not QuenchTankLidGasketMaker.maker then return false,"Potreben tesnilkar" end; return true end
function QuenchTankLidGasketMaker.make(pt,qty) qty=qty or 1; local ok,e=QuenchTankLidGasketMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then QuenchTankLidGasketMaker.ironStock=QuenchTankLidGasketMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then QuenchTankLidGasketMaker.bronzeStock=QuenchTankLidGasketMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then QuenchTankLidGasketMaker.woodStock=QuenchTankLidGasketMaker.woodStock-d.woodCost*qty end; if d.leatherCost then QuenchTankLidGasketMaker.leatherStock=QuenchTankLidGasketMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then QuenchTankLidGasketMaker.silverStock=QuenchTankLidGasketMaker.silverStock-d.silverCost*qty end; if d.goldCost then QuenchTankLidGasketMaker.goldStock=QuenchTankLidGasketMaker.goldStock-d.goldCost*qty end; if d.jewelCost then QuenchTankLidGasketMaker.jewelStock=QuenchTankLidGasketMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then QuenchTankLidGasketMaker.pearlStock=QuenchTankLidGasketMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if QuenchTankLidGasketMaker.maker then t=math.max(1,t-math.floor(QuenchTankLidGasketMaker.maker.skill/13)) end; table.insert(QuenchTankLidGasketMaker.activeMaking,{id="quenchtanklidgasket_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function QuenchTankLidGasketMaker.completeMaking(m) local q=1.0+(QuenchTankLidGasketMaker.getQualityBonus()/100); if QuenchTankLidGasketMaker.maker then q=q+(QuenchTankLidGasketMaker.maker.skill/140) end; q=math.min(2.5,q); QuenchTankLidGasketMaker.productStock[m.productType]=(QuenchTankLidGasketMaker.productStock[m.productType] or 0)+m.quantity; QuenchTankLidGasketMaker.totalProducts=QuenchTankLidGasketMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if QuenchTankLidGasketMaker.maker then QuenchTankLidGasketMaker.maker.itemsMade=QuenchTankLidGasketMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then QuenchTankLidGasketMaker.maker.skill=math.min(100,QuenchTankLidGasketMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tesnilo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"quenchtanklidgasket.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function QuenchTankLidGasketMaker.update(dt) if not _G.state then return end; QuenchTankLidGasketMaker.dayTimer=QuenchTankLidGasketMaker.dayTimer+dt; if QuenchTankLidGasketMaker.dayTimer>=30 then QuenchTankLidGasketMaker.dayTimer=0; for i=#QuenchTankLidGasketMaker.activeMaking,1,-1 do local m=QuenchTankLidGasketMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then QuenchTankLidGasketMaker.completeMaking(m); table.remove(QuenchTankLidGasketMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(QuenchTankLidGasketMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if QuenchTankLidGasketMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function QuenchTankLidGasketMaker.getStats() return {ironStock=QuenchTankLidGasketMaker.ironStock,bronzeStock=QuenchTankLidGasketMaker.bronzeStock,woodStock=QuenchTankLidGasketMaker.woodStock,leatherStock=QuenchTankLidGasketMaker.leatherStock,silverStock=QuenchTankLidGasketMaker.silverStock,goldStock=QuenchTankLidGasketMaker.goldStock,jewelStock=QuenchTankLidGasketMaker.jewelStock,pearlStock=QuenchTankLidGasketMaker.pearlStock,productStock=QuenchTankLidGasketMaker.productStock,numBuildings=#QuenchTankLidGasketMaker.buildings,hasMaker=QuenchTankLidGasketMaker.maker~=nil,makerName=QuenchTankLidGasketMaker.maker and QuenchTankLidGasketMaker.maker.name or "—",makerSkill=QuenchTankLidGasketMaker.maker and QuenchTankLidGasketMaker.maker.skill or 0,activeMaking=#QuenchTankLidGasketMaker.activeMaking,totalProducts=QuenchTankLidGasketMaker.totalProducts} end
